/* nis_blobs.S , embedded NIS SPIR-V blobs (sharpen + upscale).
 *
 * Compiled shaders live in build/ (generated by `make nis-shaders`).
 * These blobs are linked directly into libVkLayer_greenboost.so so the
 * layer works without any external .spv files at runtime.
 *
 * Symbols exported:
 *   nis_sharpen_spv_start / nis_sharpen_spv_end
 *   nis_upscale_spv_start / nis_upscale_spv_end
 *
 * Size of each blob = end - start (in bytes, always a multiple of 4).
 */

    .section .rodata,"a",%progbits

    .align 4
    .globl nis_sharpen_spv_start
    .type  nis_sharpen_spv_start, @object
nis_sharpen_spv_start:
    .incbin "build/nis_sharpen.spv"
    .globl nis_sharpen_spv_end
nis_sharpen_spv_end:

    .align 4
    .globl nis_upscale_spv_start
    .type  nis_upscale_spv_start, @object
nis_upscale_spv_start:
    .incbin "build/nis_upscale.spv"
    .globl nis_upscale_spv_end
nis_upscale_spv_end:
